using System;using System.Collections;using System.IO;using System.Reflection;using UnityEngine;
// Both AIs use the normal controller, animation, collisions, goals and serve resets.
public sealed class FormlessSelfPlayTests:MonoBehaviour {
 public static bool UseAI;public static bool ReadKey(KeyCode k){return false;}public static bool ReadDown(KeyCode k){return false;}static bool booted;
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=Path.Combine(Application.dataPath,"..","contest-selfplay-bindings.ini");var o=new GameObject("FormlessSelfPlayTests");DontDestroyOnLoad(o);o.AddComponent<FormlessSelfPlayTests>();}
 const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 [Serializable]public sealed class Results{public string policyHash;public int fanFormlessShots,zhaoFormlessShots,fanBicycleShots,zhaoBicycleShots;public int formlessShots,bicycleAttempts,bicycleStarts,bicycleShots,lowQualityShots,mediumQualityShots,highQualityShots;public int cannonLobs,cannonContacts,leafContacts,rescueAttempts,ability0Goals,ability8Goals,ability10Goals,ability12Goals,ability13Goals,ability22Goals,lowSumCannonContacts,baselineSumCannonContacts,highSumCannonContacts;public int target=200,goals,fanGoals,zhaoGoals,highGoals,lowGoals,specialSamples,abilitySamples,matches,failures,physicsSteps,bodySteps,feetSteps,chestSteps,headSteps,highContactWins,lowContactWins;public float realSeconds,simulatedSeconds,maxJointError,highContactPush,lowContactPush,feetHighPush,feetLowPush,chestHighPush,chestLowPush,headHighPush,headLowPush,bodyHighPush,bodyLowPush;}
 static FormlessSelfPlayTests current;public static void Cannon(){if(current!=null&&current.ready){current.results.cannonContacts++;if(AbilityMode.Enabled){int total=AbilityMode.CannonTotal(current.fan);if(total<12)current.results.lowSumCannonContacts++;else if(total==12)current.results.baselineSumCannonContacts++;else current.results.highSumCannonContacts++;}}}public static void Lobbed(){if(current!=null&&current.ready)current.results.cannonLobs++;}public static void Leaf(){if(current!=null&&current.ready)current.results.leafContacts++;}public static void Rescue(){if(current!=null&&current.ready)current.results.rescueAttempts++;}Results results=new Results();int[] played=new int[2];bool ready;int highSide,lastFan,lastZhao;float began,lastSave,matchBegan,prevMiddle,lastGoal;Component fan,zhao,manager;Rigidbody2D fb,zb,ball;BuildPlayer fp,zp;FieldInfo p1,p2,stopping;StreamWriter events,matches;string root,progress;float speed=24;bool priorContact;readonly ContactPoint2D[] contacts=new ContactPoint2D[32];
 public static void Attempt(){if(current!=null&&current.ready)current.results.bicycleAttempts++;}public static void Started(){if(current!=null&&current.ready)current.results.bicycleStarts++;}public static void Shot(Component actor,bool bicycle,int quality){if(current==null||!current.ready)return;current.results.formlessShots++;if(actor.name=="Fan")current.results.fanFormlessShots++;else current.results.zhaoFormlessShots++;if(bicycle){current.results.bicycleShots++;if(actor.name=="Fan")current.results.fanBicycleShots++;else current.results.zhaoBicycleShots++;if(quality==0)current.results.lowQualityShots++;else if(quality==1)current.results.mediumQualityShots++;else current.results.highQualityShots++;}}
 void Save(){results.realSeconds=Time.realtimeSinceStartup-began;File.WriteAllText(progress,JsonUtility.ToJson(results,true));events.Flush();matches.Flush();}
 void Fail(string message){results.failures++;Debug.LogError("SELFPLAY FAIL "+message);Save();Application.Quit(1);ready=UseAI=false;}
 void Goal(bool zhaoScored){if(played[highSide]>=results.target/2)return;results.goals++;played[highSide]++;if(zhaoScored)results.zhaoGoals++;else results.fanGoals++;bool highScored=(zhaoScored?1:0)==highSide;if(highScored)results.highGoals++;else results.lowGoals++;if(highSide==0)results.specialSamples++;else {results.abilitySamples++;switch(AbilityMode.CannonTotal(fan)){case 0:results.ability0Goals++;break;case 8:results.ability8Goals++;break;case 10:results.ability10Goals++;break;case 12:results.ability12Goals++;break;case 13:results.ability13Goals++;break;case 22:results.ability22Goals++;break;}}lastGoal=Time.time;events.WriteLine(results.goals+","+results.matches+","+(zhaoScored?"Zhao":"Fan")+","+(highSide==0?"Special":"Allocated")+","+(zhaoScored?-1:1)+","+((int)p1.GetValue(manager))+","+((int)p2.GetValue(manager))+","+Time.time+","+ball.position.x+","+ball.position.y+","+(highSide==0?-1:AbilityMode.CannonTotal(fan)));Save();if(results.goals%10==0)Debug.Log("SELFPLAY GOALS "+results.goals+"/"+results.target+" high="+results.highGoals+" low="+results.lowGoals);}
 int BallParts(Component player){int bits=0,count=ball.GetComponent<Collider2D>().GetContacts(contacts);for(int i=0;i<count;i++){var c=contacts[i].collider;var d=contacts[i].otherCollider;if(c!=null&&c.transform.IsChildOf(player.transform)){if(c.name=="Head")bits|=4;else if(c.name=="Body")bits|=2;else if(c.name.IndexOf("Leg",StringComparison.OrdinalIgnoreCase)>=0||c.name.IndexOf("Foot",StringComparison.OrdinalIgnoreCase)>=0)bits|=1;}if(d!=null&&d.transform.IsChildOf(player.transform)){if(d.name=="Head")bits|=4;else if(d.name=="Body")bits|=2;else if(d.name.IndexOf("Leg",StringComparison.OrdinalIgnoreCase)>=0||d.name.IndexOf("Foot",StringComparison.OrdinalIgnoreCase)>=0)bits|=1;}}return bits;}
 void Rig(Component c){foreach(var j in c.GetComponentsInChildren<HingeJoint2D>()){if(j.connectedBody==null){Fail("broken joint "+c.name);return;}float e=Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor));if(float.IsNaN(e)||float.IsInfinity(e)){Fail("invalid rig "+c.name);return;}results.maxJointError=Mathf.Max(results.maxJointError,e);}}
 void FixedUpdate(){if(!ready||manager==null||fb==null||zb==null)return;results.physicsSteps++;int a=(int)p1.GetValue(manager),b=(int)p2.GetValue(manager);while(lastFan<a){lastFan++;Goal(false);}while(lastZhao<b){lastZhao++;Goal(true);}if((bool)stopping.GetValue(manager)||Time.timeScale<=0){priorContact=false;return;}
 bool linked=fp!=null&&zp!=null&&fp.InContest;int parts=linked?BallParts(fan)&BallParts(zhao):0;float middle=(fb.position.x+zb.position.x)*.5f;float sign=highSide==0?1:-1;if(linked&&priorContact){float push=(middle-prevMiddle)*sign;if(Mathf.Abs(push)<.12f){if(push>.001f){results.highContactWins++;results.highContactPush+=push;if((parts&1)!=0)results.feetHighPush+=push;else if((parts&2)!=0)results.chestHighPush+=push;else if((parts&4)!=0)results.headHighPush+=push;else results.bodyHighPush+=push;}else if(push<-.001f){results.lowContactWins++;results.lowContactPush-=push;if((parts&1)!=0)results.feetLowPush-=push;else if((parts&2)!=0)results.chestLowPush-=push;else if((parts&4)!=0)results.headLowPush-=push;else results.bodyLowPush-=push;}}}
 if(linked){if((parts&1)!=0)results.feetSteps++;else if((parts&2)!=0)results.chestSteps++;else if((parts&4)!=0)results.headSteps++;else results.bodySteps++;}prevMiddle=middle;priorContact=linked;
 if(results.physicsSteps%25==0){Rig(fan);Rig(zhao);}if(Time.realtimeSinceStartup-lastSave>15){lastSave=Time.realtimeSinceStartup;Save();Debug.Log("SELFPLAY PROGRESS goals="+results.goals+"/"+results.target+" matches="+results.matches+" high="+results.highGoals+" low="+results.lowGoals+" contacts="+(results.bodySteps+results.feetSteps+results.chestSteps+results.headSteps));}}
 void RuntimeLog(string message,string stack,LogType type){if(type==LogType.Exception){results.failures++;ready=UseAI=false;if(events!=null&&matches!=null)Save();Application.Quit(1);}}
 IEnumerator Start(){Application.logMessageReceived+=RuntimeLog;current=this;began=Time.realtimeSinceStartup;Application.runInBackground=true;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;AudioListener.volume=0;Time.maximumDeltaTime=.02f;root=Path.Combine(Application.dataPath,"..");progress=Path.Combine(root,"contest-selfplay-progress.json");string[] args=Environment.GetCommandLineArgs();for(int i=0;i+1<args.Length;i++){if(args[i]=="-selfplayGoals")int.TryParse(args[i+1],out results.target);if(args[i]=="-selfplaySpeed")float.TryParse(args[i+1],out speed);if(args[i]=="-policyHash")results.policyHash=args[i+1];}if(results.target<2||results.target%2!=0||string.IsNullOrEmpty(results.policyHash))throw new InvalidOperationException("Invalid selfplay manifest");events=new StreamWriter(Path.Combine(root,"contest-selfplay-goals.csv"));matches=new StreamWriter(Path.Combine(root,"contest-selfplay-matches.csv"));events.WriteLine("goal,match,scorer,mode,fan_reward,fan_score,zhao_score,time,ball_x,ball_y,stat_total");matches.WriteLine("match,mode,fan_score,zhao_score,sim_seconds");yield return null;
 while(results.goals<results.target){ready=UseAI=false;Time.timeScale=1;AbilityMode.SetBudget(24);AbilityMode.Reset();highSide=results.matches%2;if(played[highSide]>=results.target/2)highSide=1-highSide;PlayerSkills.Enabled=highSide==0;AbilityMode.Enabled=highSide==1;int profileEnd=results.target/2;if(highSide==1){int stage=Mathf.Min(5,played[1]/Mathf.Max(1,results.target/12));int[][] profiles={new int[]{0,0,0},new int[]{3,3,2},new int[]{4,4,2},new int[]{4,4,4},new int[]{5,4,4},new int[]{8,6,8}};profileEnd=stage==5?results.target/2:(stage+1)*Mathf.Max(1,results.target/12);for(int side=0;side<2;side++){for(int i=0;i<3;i++)AbilityMode.Builds[side].Levels[i]=profiles[stage][i];AbilityMode.Builds[side].Purchased=1<<10;}}ControlBindings.ResetDefaults();UnityEngine.Random.InitState(28711+results.matches);typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.35f);
 Type pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);fp=fan.GetComponent<BuildPlayer>();zp=zhao.GetComponent<BuildPlayer>();manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();p1=manager.GetType().GetField("p1Score",IP);p2=manager.GetType().GetField("p2Score",IP);stopping=manager.GetType().GetField("isStopping",IP);lastFan=(int)p1.GetValue(manager);lastZhao=(int)p2.GetValue(manager);foreach(var a in FindObjectsOfType<Animator>())a.cullingMode=AnimatorCullingMode.AlwaysAnimate;results.matches++;matchBegan=lastGoal=Time.time;priorContact=false;ready=UseAI=true;
 while(results.goals<results.target&&played[highSide]<profileEnd&&Time.time-matchBegan<90){Time.timeScale=speed;yield return null;if(manager==null)break;}
 ready=UseAI=false;results.simulatedSeconds+=Time.time-matchBegan;matches.WriteLine(results.matches+","+(highSide==0?"Special":"Allocated")+","+lastFan+","+lastZhao+","+(Time.time-matchBegan));Save();if(results.matches>2000){Fail("too many complete matches without requested goals");yield break;}}
 ready=UseAI=false;Time.timeScale=1;Save();events.Dispose();matches.Dispose();events=matches=null;Debug.Log("SELFPLAY COMPLETE goals="+results.goals+" fan="+results.fanGoals+" zhao="+results.zhaoGoals+" high="+results.highGoals+" low="+results.lowGoals+" matches="+results.matches+" failures="+results.failures);Application.Quit(results.failures==0?0:1);}
 void OnApplicationQuit(){if(events!=null)events.Flush();if(matches!=null)matches.Flush();}
